  (* [comment removed for export] *)
  Lemma z32_join2 : forall p pt nb B flag mm (x5 x7 x8 x25 x29 x31 : word),
    Z32M mm -> DST <= p <= DST + Qe -> 2 <= Qe ->
    0 <= nb <= pt -> nb <= 8 -> pt + 8 <= Lk -> 0 <= B <= 64 -> (flag = 0 \/ (flag = 1 /\ B <= 7)) ->
    (forall p' pt' B' (CZ' : Z) mm' (x5' x7' x11' x16' x25' x31' : word),
       Z32M mm' -> 0 <= CZ' < 2^64 -> p < p' <= DST + Qe -> 0 <= pt' -> (pt' = 0 \/ pt' + 8 <= Lk) -> 0 <= B' <= 64 ->
       evtF asegs RNG POST (ZC 0x8b3a0 mm' (Z_to_bv 64 B') x5' (Z_to_bv 64 (DST + Qe)) x7' (Z_to_bv 64 CZ') x11'
                               (Z_to_bv 64 (SS + O + pt')) (Z_to_bv 64 p') x16' (Z_to_bv 64 64) y9 x25'
                               (Z_to_bv 64 (DST + Qe - 2)) x29 (Z_to_bv 64 (64 - tl)) x31')) ->
    evtF asegs RNG POST (ZC 0x8b3dc mm (Z_to_bv 64 B) x5 (Z_to_bv 64 (DST + Qe)) x7 x8 (Z_to_bv 64 flag)
                            (Z_to_bv 64 (SS + O + pt)) (Z_to_bv 64 p) (Z_to_bv 64 nb) (Z_to_bv 64 64) y9 x25
